import React, { useState } from "react";
import { Link } from "react-router-dom";
import toast from "react-hot-toast";
import Rating from "./Rating"; 

const ProductCard = ({ product, onAddToCart }) => {
  const [selectedVariant, setSelectedVariant] = useState("Default");

  // Mock stock availability (simulate using product.id for now)
  const isInStock = product.id % 4 !== 0;

  const mockVariants = ["Default", "Small", "Medium", "Large"];

  const handleAddToCart = () => {
    toast.success(`Added ${selectedVariant} to cart`);
    onAddToCart({ ...product, selectedVariant });
  };

  return (
    <div className="col-md-4 col-sm-6 col-xs-8 col-12 mb-4" id={String(product.id)}>
      <div className="card h-100 shadow-sm border-0 rounded-4">
        <img
          className="card-img-top object-fit-contain p-3"
          src={product.image}
          alt={product.title}
          style={{ height: '250px' }}
        />
        <div className="text-center m-auto">
          <Rating value={product.rating?.rate || 0} count={product.rating?.count} />
        </div>

        <div className="card-body text-start">
          <h5 className="card-title fw-bold">
            {product.title.substring(0, 20)}...
          </h5>
          <p className="card-text text-muted small">
            {product.description.substring(0, 90)}...
          </p>

          {/* Variant Dropdown */}
          <label htmlFor={`variant-${product.id}`} className="form-label mt-2">
            Choose Variant
          </label>
          <select
            id={`variant-${product.id}`}
            className="form-select mb-3"
            value={selectedVariant}
            onChange={(e) => setSelectedVariant(e.target.value)}
            disabled={!isInStock}
          >
            {mockVariants.map((variant) => (
              <option key={variant} value={variant}>
                {variant}
              </option>
            ))}
          </select>
        </div>

        <ul className="list-group list-group-flush">
          <li className="list-group-item lead">$ {product.price}</li>
        </ul>

        <div className="card-body">
          {isInStock ? (
            <>
              <Link to={`/product/${product.id}`} className="btn btn-dark m-1">
                Buy Now
              </Link>
              <button className="btn btn-dark m-1" onClick={handleAddToCart}>
                Add to Cart
              </button>
            </>
          ) : (
            <span className="badge bg-secondary px-3 py-2">Out of Stock</span>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductCard;
